class Solution:
    def canConstruct(self, ransomNote: str, magazine: str) -> bool:
        from collections import Counter
        mag_count = Counter(magazine)
        for c in ransomNote:
            if mag_count[c] <= 0:
                return False
            mag_count[c] -= 1
        return True

